<?php
namespace App\Extensions\ChatbotEcommerce\System\Services;use App\Extensions\ChatbotEcommerce\System\Models\Product;use App\Extensions\ChatbotEcommerce\System\Models\Coupon;
class CommerceRuntime{public function products(array$f=[]){return Product::query()->where('active',true)->when($f['q']??null,fn($q,$v)=>$q->where('name','like',"%$v%"))->paginate((int)($f['per_page']??24));}public function validateCoupon(string$code,int$subtotal):?Coupon{return Coupon::query()->where('code',$code)->where('active',true)->where(fn($q)=>$q->whereNull('starts_at')->orWhere('starts_at','<=',now()))->where(fn($q)=>$q->whereNull('ends_at')->orWhere('ends_at','>=',now()))->where('minimum_amount','<=',$subtotal)->first();}public function recommend(array$context){return Product::query()->where('active',true)->orderByDesc('recommendation_score')->limit(8)->get();}}
